export const getLinkingConfigParamsPath = screen => {
  var nav = linking?.config?.screens;

  if (nav['Main']?.screens[screen]) nav = nav['Main']?.screens;

  return nav[screen]?.screens[screen]?.path;
};

const uriFormat = uri => {
  return (argSep = /.*:\/\/[^\?\/]*(.).*/.exec(uri)[1] == '/' ? 'rn' : '');
};

// Ver https://github.com/tokkozhin/react-native-qrcode-styled/issues/4#issuecomment-1893453222
export const QRCode = props => {
  const [width, setWidth] = useState(0);
  const { data, sizePc, padding, logo, gradient, props: parentProps } = props;
  const qrdata = useQRCodeData(data ?? '1', {});

  const styles = StyleSheet.create({
    root: {
      justifyContent: 'center',
      alignItems: 'center',
    },
    svg: {
      backgroundColor: '#fff',
      borderRadius: 20,
      overflow: 'hidden',
    },
    logoContainer: {
      position: 'absolute',
      width: 88,
      height: 88,
      backgroundColor: '#fff',
      justifyContent: 'center',
      alignItems: 'center',
    },
    logo: {
      width: '90%',
      height: '90%',
      top: -2,
    },
  });
  // console.log(jlog({parentProps}));

  return (
    <View
      {...parentProps}
      onLayout={event => {
        const layoutProps = event.nativeEvent.layout;
        const { width, height } = layoutProps;
        setWidth(width);
        // console.log(`width: ${width}, height: ${height}`);
        // console.log(jlog({layoutProps}));
      }}
      style={{ flex: 1, alignItems: 'center', justifyContent: 'center' }}
    >
      <QRCodeStyled
        {...parentProps}
        data={data ?? '1'}
        pieceSize={
          (((width - 2 * (padding ?? 0)) / qrdata.qrCodeSize) *
            (sizePc ?? 100)) /
          100
        }
        pieceScale={1.02} // fix small gap between pieces
        style={{ backgroundColor: 'white' }}
        padding={padding ?? 0}
        // pieceCornerType={'cut'}
        // pieceBorderRadius={[4, 0, 4]}

        outerEyesOptions={{
          color: '#ffa114',
          topLeft: {
            color: '#ffa114',
            borderRadius: [20, 20, 0, 20],
          },
          topRight: {
            color: '#ffa114',
            borderRadius: [20, 20, 20],
          },
          bottomLeft: {
            color: '#ffa114',
            borderRadius: [20, 0, 20, 20],
          },
        }}
        innerEyesOptions={{
          color: '#464E58FF',
          borderRadius: 12,
          scale: 0.85,
        }}
        gradient={
          gradient && {
            type: 'linear',
            options: {
              start: [0, 0],
              end: [1, 1],
              // colors: ['#da0c8b', '#00bfff'],
              // colors: ['#0DA129FF', '#00bfff'],  // Green to Bkue

              // colors: ['#ffa114', '#464E58FF'],
              // colors: ['#ffa114', '#00bfff'],   // Orange to Blue
              // colors: ['#ffa114', '#0DA129FF'],   // Orange to Green
              colors: [gradient[0] ?? '#00bfff', gradient[1] ?? '#0DA129FF'], // Blue to Green
              locations: [0, 1],
            },
          }
        }
      />

      {logo ? (
        <View style={styles.logoContainer}>
          <Image
            // source={imageSource(Images['d'])}
            source={logo}
            style={styles.logo}
          />
        </View>
      ) : null}
    </View>
  );
};

export const PunchQR = props => {
  const {
    app = 'dss',
    screen = 'punch',
    RNUrl = true,
    companyId,
    taskId,
    costId,
    direction,
    locationId,
    expires,
    signKey,
    ts,
    signLength = 32,
    gradient,
    props: parentProps,
  } = props;

  // console.log(`props: ${JSON.stringify(props)}`);
  const [location, setLocation] = useState(null);
  const dimensions = useWindowDimensions();

  useEffect(() => {
    (async () => {
      let { status } = await Location.requestForegroundPermissionsAsync();
      if (status !== 'granted') {
        console.log('Permission to access location was denied');
      }
      console.log('Permission to access location granted');

      let location = await Location.getCurrentPositionAsync({});
      setLocation(location);
    })();
  }, []);

  const payload = () => {
    var qrdata = `${app}://${screen}`;
    const argSep = RNUrl ? '/' : '?';
    // console.log(`qrdata: ${qrdata}`);                             // QrpunchScreen/:ti?/:ex?/:ms?/:ci?/:cc?/:li?/:d?/:ll?/:lt?

    // const paramsPath = linking?.config?.screens[screen]?.screens[screen]?.path;

    // console.log(`linking?.config?.screens[screen]: ${JSON.stringify(linking?.config?.screens[screen], undefined, 2)}`);

    const paramsPath = getLinkingConfigParamsPath(screen);
    // const paramsPath = 'QrpunchScreen/:ti?/:ex?/:ms?/:ci?/:cc?/:li?/:d?/:ll?/:lt?'
    // console.log(`linking: ${JSON.stringify(linking)}`);
    // console.log(`paramsPath: ${paramsPath}`);                             // QrpunchScreen/:ti?/:ex?/:ms?/:ci?/:cc?/:li?/:d?/:ll?/:lt?

    const FieldOrder = /[^\/](\/.*)/.exec(paramsPath)[1].slice(1);

    // console.log(`PunchQR:ts: ${ts}`);

    var Fields = {
      cc: costId,
      ci: companyId,
      d: direction,
      ex: Math.floor((ts ?? new Date())?.valueOf() / 1000) + expires,
      li: locationId,
      ll: null,
      lt: null,
      ms: null,
      ti: taskId,
    };
    // console.log(`Fields: ${JSON.stringify(Fields)}`);

    if (location) {
      Fields.lt = `${location?.coords?.latitude}`;
      Fields.ll = `${location?.coords?.longitude}`;
    }

    if (signKey != undefined) {
      const rawArgs = QRUri.BuildArgs(Fields, FieldOrder, RNUrl, false);
      Fields['ms'] = MD5(`${qrdata}${rawArgs}|${signKey}`).slice(0, signLength);
    }

    const signedArgs = QRUri.BuildArgs(Fields, FieldOrder, RNUrl, true);
    // console.log(`signedArgs: ${signedArgs}`);

    if (signedArgs.length) qrdata += signedArgs;

    console.log(`PunchQR: ${qrdata}`);

    // check(qrdata, {signature: signKey, distance: 100, fields: FieldOrder}).then ( rslt =>  console.log(`Check: ${rslt}`) )
    QRUri.CheckUriAsync(qrdata, {
      signature: signKey,
      distance: 100,
      fields: FieldOrder,
    }).then(rslt => console.log(`Check: ${rslt}`));

    return qrdata;
  };

  const qdata = useMemo(
    () =>
      // payload(companyId, taskId, costId, direction, locationId, location, expires, signKey, ts, signLength),
      payload(),
    [
      app,
      screen,
      RNUrl,
      companyId,
      taskId,
      costId,
      direction,
      locationId,
      location,
      expires,
      signKey,
      ts,
      signLength,
    ]
  );

  return (
    <>
      {!location ? (
        <View
          style={StyleSheet.applyWidth(
            {
              alignSelf: 'center',
              flexWrap: 'wrap',
              height: 300,
              justifyContent: 'center',
              padding: 30,
              width: '100%',
            },
            dimensions.width
          )}
        >
          <Text
            accessible={true}
            {...GlobalStyles.TextStyles(parentProps.theme)['Text 2'].props}
            style={StyleSheet.applyWidth(
              StyleSheet.compose(
                GlobalStyles.TextStyles(parentProps.theme)['Text 2'].style,
                {
                  color: parentProps.theme.colors.branding.secondary,
                  fontFamily: 'System',
                  fontSize: 18,
                  fontWeight: '700',
                  textAlign: 'center',
                }
              ),
              dimensions.width
            )}
          >
            {'Obteniendo Localización...'}
          </Text>
        </View>
      ) : (
        <QRCode
          {...parentProps}
          {...props}
          data={qdata}
          logo={imageSource(Images['d'])}
        />
      )}
    </>
  );
};
