import * as Draftbit from '../custom-files/Draftbit';

const UpdateRequestQuotas = async Variables => {
  const aQuota = (
    await Draftbit.DcSSApi.requestQuotaGET(Variables, {
      emp_id: Variables['my_emp_id'],
    })
  )?.json;

  // console.log(`UpdateRequestQuotas: ${JSON.stringify(aQuota, undefined, 2)}`)

  return aQuota.error ? [] : aQuota;
};

export default UpdateRequestQuotas;
